import React from 'react';
import {render, screen, fireEvent} from '@testing-library/react-native';
import Onyx from 'react-native-onyx';
import ONYXKEYS from '@src/ONYXKEYS';
import AddBankAccountPage from '../AddBankAccountPage';
import * as ReimbursementAccountProps from '@pages/ReimbursementAccount/reimbursementAccountPropTypes';

jest.mock('@hooks/useLocalize', () => () => ({
    translate: jest.fn(key => key),
}));

describe('AddBankAccountPage', () => {
    beforeAll(() => {
        Onyx.init({
            keys: ONYXKEYS,
        });
    });

    beforeEach(() => {
        Onyx.clear();
    });

    it('should update the account number when the user goes back to the manual entry step and edits it', () => {
        const reimbursementAccount = {
            ...ReimbursementAccountProps.reimbursementAccountDefaultProps,
            achData: {
                accountNumber: '1111222233334444',
                routingNumber: '011401533',
                bankAccountID: 1,
            },
        };
        Onyx.set(ONYXKEYS.REIMBURSEMENT_ACCOUNT, reimbursementAccount);
        Onyx.set(ONYXKEYS.FORMS.REIMBURSEMENT_ACCOUNT_FORM_DRAFT, reimbursementAccount.achData);

        render(<AddBankAccountPage />);

        // Simulate user navigation
        const backButton = screen.getByText('common.back');
        fireEvent.press(backButton);

        const accountNumberInput = screen.getByLabelText('bankAccount.accountNumber');
        fireEvent.changeText(accountNumberInput, '1111222233331111');

        const nextButton = screen.getByText('common.next');
        fireEvent.press(nextButton);

        const updatedDraft = Onyx.get(ONYXKEYS.FORMS.REIMBURSEMENT_ACCOUNT_FORM_DRAFT);
        expect(updatedDraft.accountNumber).toBe('1111222233331111');
    });
});

